// simple instruments, with a trigger and an accent CV.  Numerals
// will control the accent CV.  0 = 10% -> 9 == 100%

sound(kick,#,yellow,29) = {
0,0: T   // trigger
0,1: N   // accent CV
}

sound(kick,X,orange,30) = {
0,0: T   // trigger
0,1: 50   // accent CV
0,2: 100,100,100,90,90,90,80,80
}

sound(kick,Z,red,31) = {
0,0: T    // trigger
0,1: 100   // accent CV
0,2: 100,100,100,90,90,90,80,80
}

sound(tomHi,#,1,green) = {
